<script lang="ts">
  import { Bot, Check, ChevronRight, Copy, Edit3, Plus, RefreshCw, Search, Shield, ShieldCheck, Star, Wrench, X } from 'lucide-svelte';
  import { api, ApiError, type PersonaCatalogItem, type PersonaVersion } from '../../lib/api';

  export let profiles: PersonaCatalogItem[] = [];
  export let scopeName: (id: string) => string;
  export let formatDate: (value: string) => string;
  export let onNotice: (message: string) => void;
  export let onError: (message: string) => void;

  let query = '';
  let selectedProfileId = '';
  let selectedVersionId = '';
  let versions: PersonaVersion[] = [];
  let profileInstruction = '';
  let profileCapabilities = 'text, tool_calling, stream';
  let profileAllowedTools = '';
  let profileInputSchema = '{"type":"object","additionalProperties":true}';
  let profileOutputSchema = '{"type":"object","additionalProperties":true}';
  let detailTab: 'overview' | 'versions' | 'contract' = 'overview';
  let editorOpen = false;
  let busy = false;
  let loading = false;
  let favoriteIds: string[] = [];

  $: filteredProfiles = profiles.filter((profile) => `${profile.name} ${profile.description} ${profile.status} ${scopeName(profile.scope_id)}`.toLowerCase().includes(query.trim().toLowerCase()));
  $: selectedProfile = profiles.find((profile) => profile.id === selectedProfileId) ?? null;
  $: selectedVersion = versions.find((version) => version.id === selectedVersionId) ?? null;
  $: groupedProfiles = [
    { key: 'manager', title: '职能层 · Manager', icon: Bot, description: '理解运维问题，自主拆解并分派资源专家，汇总因果结论。', items: filteredProfiles.filter((profile) => /manager|管理|协同|审计/i.test(`${profile.name} ${profile.description}`)) },
    { key: 'worker', title: '资源层 · Worker', icon: Wrench, description: '掌握域内诊断技能，执行单资源深度诊断分析。', items: filteredProfiles.filter((profile) => !/manager|管理|协同|审计/i.test(`${profile.name} ${profile.description}`)) }
  ];

  function describeError(error: unknown, fallback: string) { if (error instanceof ApiError) { if (error.status === 403) return '当前账号没有执行此操作的权限。'; if (error.status === 401) return '会话已过期，请重新登录。'; return error.message || fallback; } if (error instanceof SyntaxError) return '配置必须是有效的 JSON 对象。'; return error instanceof Error ? error.message || fallback : fallback; }
  function selectedConfig(key: string, fallback: unknown = '') { return selectedVersion?.config?.[key] ?? selectedProfile?.config?.[key] ?? fallback; }
  function configText(key: string, fallback = '') { const value = selectedConfig(key, fallback); return Array.isArray(value) ? value.join(', ') : String(value ?? fallback); }
  function profileType(profile: PersonaCatalogItem) { return /manager|管理|协同|审计/i.test(`${profile.name} ${profile.description}`) ? 'Manager' : 'Worker'; }
  function profileEngine(profile: PersonaCatalogItem) { return String(profile.config?.engine ?? profile.config?.provider ?? (profileType(profile) === 'Manager' ? 'Anthropic AI SDK' : '默认引擎')); }
  function profileDomain(profile: PersonaCatalogItem) { return String(profile.config?.domain ?? profile.config?.resource_kind ?? (profile.name.replace(/专家|协同|审计|诊断|优化/g, '').trim() || '通用')); }
  function profileLimits(profile: PersonaCatalogItem) { return String(profile.config?.dispatch_limit ?? profile.config?.max_concurrency ?? (profileType(profile) === 'Manager' ? '5' : '—')); }
  function profileCapabilitiesText(profile: PersonaCatalogItem) { return String(profile.config?.capabilities ?? profile.config?.skills ?? (profileType(profile) === 'Manager' ? '理解 · 分派 · 汇总' : '资源诊断')); }
  function toggleFavorite(id: string) { favoriteIds = favoriteIds.includes(id) ? favoriteIds.filter((item) => item !== id) : [...favoriteIds, id]; }
  async function loadVersions(profileID = selectedProfileId, open = false) { if (!profileID) return; loading = true; try { versions = await api.personaVersions(profileID); selectedVersionId = versions.find((item) => item.status === 'published')?.id || versions[0]?.id || ''; if (open) { selectedProfileId = profileID; detailTab = 'overview'; editorOpen = false; } } catch (error) { onError(describeError(error, 'Persona 版本加载失败')); } finally { loading = false; } }
  function selectProfile(profile: PersonaCatalogItem) { selectedProfileId = profile.id; void loadVersions(profile.id, true); }
  async function openEdit(profile: PersonaCatalogItem) { await loadVersions(profile.id, true); resetEditor(versions.find((item) => item.id === selectedVersionId)); editorOpen = true; }
  function resetEditor(version = selectedVersion) { const config = version?.config ?? {}; profileInstruction = String(config.instruction ?? ''); profileCapabilities = Array.isArray(config.capabilities) ? config.capabilities.join(', ') : String(config.capabilities ?? 'text, tool_calling, stream'); profileAllowedTools = Array.isArray(config.allowed_tools) ? config.allowed_tools.join(', ') : String(config.allowed_tools ?? ''); profileInputSchema = JSON.stringify(config.input_schema ?? { type: 'object', additionalProperties: true }, null, 2); profileOutputSchema = JSON.stringify(config.output_schema ?? { type: 'object', additionalProperties: true }, null, 2); }
  function startCreate() { if (!selectedProfile && filteredProfiles[0]) selectProfile(filteredProfiles[0]); resetEditor(); editorOpen = true; }
  function startEdit() { resetEditor(); editorOpen = true; }
  async function createVersion() { if (!selectedProfileId || !profileInstruction.trim()) return; busy = true; onError(''); try { const config = { version: 1, instruction: profileInstruction.trim(), capabilities: profileCapabilities.split(',').map((item) => item.trim()).filter(Boolean), allowed_tools: profileAllowedTools.split(',').map((item) => item.trim()).filter(Boolean), input_schema: JSON.parse(profileInputSchema), output_schema: JSON.parse(profileOutputSchema), enabled: true }; const version = await api.createPersonaVersion(selectedProfileId, config); selectedVersionId = version.id; versions = [version, ...versions]; editorOpen = false; onNotice(`专家 v${version.version} 草稿已创建`); } catch (error) { onError(describeError(error, '创建专家版本失败')); } finally { busy = false; } }
  async function publishVersion() { if (!selectedProfileId || !selectedVersionId) return; busy = true; onError(''); try { await api.publishPersonaVersion(selectedProfileId, selectedVersionId); await loadVersions(); onNotice('Persona 版本已发布'); } catch (error) { onError(describeError(error, '发布 Persona 版本失败')); } finally { busy = false; } }
  function closeDetail() { selectedProfileId = ''; selectedVersionId = ''; versions = []; editorOpen = false; }
</script>

<section class="persona-page">
  <header class="persona-page-header"><div><div class="persona-title"><Shield size={21} aria-hidden="true" /><h1>专家库</h1></div><p>专家库 · 共 {profiles.length} 个，已匹配 {filteredProfiles.length}。职能 Agent 负责拆解与汇总，资源 Agent 执行域内诊断。</p></div><div class="persona-header-actions"><button class="primary" type="button" on:click={startCreate} disabled={profiles.length === 0}><Plus size={16} />创建专家</button><button class="secondary" type="button" on:click={() => selectedProfile && loadVersions()}><RefreshCw size={15} />刷新</button></div></header>
  <div class="persona-toolbar"><label class="persona-search"><Search size={15} /><span class="sr-only">搜索专家</span><input bind:value={query} placeholder="搜索名称 / 领域 / 提示词" /></label><span class="persona-toolbar-count">{favoriteIds.length} 个收藏 · {profiles.length} 个专家</span></div>
  {#if filteredProfiles.length === 0}<div class="persona-empty panel"><Bot size={28} /><strong>没有匹配的专家</strong><span>请调整搜索条件，或选择一个已有专家创建版本。</span></div>{/if}
  {#each groupedProfiles as group}
    {#if group.items.length > 0}<section class="persona-group"><div class="persona-group-heading"><div class="persona-group-title"><svelte:component this={group.icon} size={16} aria-hidden="true" /><strong>{group.title}</strong><span>{group.description}</span></div></div><div class="persona-card-grid">{#each group.items as profile}
      <!-- svelte-ignore a11y_no_noninteractive_tabindex a11y_no_noninteractive_element_interactions a11y_no_noninteractive_element_to_interactive_role -->
      <article class:selected={selectedProfileId === profile.id} class="persona-card" on:click={() => selectProfile(profile)} role="button" tabindex="0" on:keydown={(event) => (event.key === 'Enter' || event.key === ' ') && selectProfile(profile)}><div class="persona-card-top"><div class="persona-card-name"><Bot size={17} aria-hidden="true" /><h2>{profile.name}</h2><span class="persona-built-in">{profile.status === 'active' ? '内置' : profile.status}</span></div><button class="icon-button" type="button" aria-label="收藏专家" on:click|stopPropagation={() => toggleFavorite(profile.id)}><Star size={17} fill={favoriteIds.includes(profile.id) ? 'currentColor' : 'none'} /></button></div><div class="persona-card-tags"><span>{profileType(profile)}</span><span>{profileDomain(profile)}</span>{#if profileCapabilitiesText(profile)}<span>{profileCapabilitiesText(profile)}</span>{/if}</div><div class="persona-card-facts"><div><span>执行引擎</span><strong>{profileEngine(profile)}</strong></div><div><span>{profileType(profile) === 'Manager' ? '可分派专家' : '已启用技能'}</span><strong>{profileType(profile) === 'Manager' ? 'pg / redis / k8s' : '全部（默认）'}</strong></div><div><span>调度上限</span><strong>{profileLimits(profile)}</strong></div></div><div class="persona-prompt"><small>系统提示词</small><p>{profile.description || '该专家尚未填写说明。'}</p></div><div class="persona-card-actions"><button class="primary" type="button" on:click|stopPropagation={() => onNotice(`已选择专家：${profile.name}`)}><Bot size={15} />使用专家</button><button class="secondary" type="button" on:click|stopPropagation={() => openEdit(profile)}><Edit3 size={15} />编辑</button></div></article>{/each}</div></section>{/if}
  {/each}
  {#if selectedProfile}<aside class="persona-detail-panel panel"><div class="persona-detail-header"><div><p class="eyebrow">PERSONA PROFILE</p><h2>{selectedProfile.name}</h2><small>{profileType(selectedProfile)} · {scopeName(selectedProfile.scope_id)}</small></div><button class="icon-button" type="button" aria-label="关闭详情" on:click={closeDetail}><X size={17} /></button></div><div class="persona-detail-meta"><span class="persona-built-in">{selectedProfile.status === 'active' ? '内置' : selectedProfile.status}</span><span>{versions.length} 个版本</span><span>{profileEngine(selectedProfile)}</span></div><nav class="persona-detail-tabs"><button class:active={detailTab === 'overview'} on:click={() => (detailTab = 'overview')}>概览</button><button class:active={detailTab === 'contract'} on:click={() => (detailTab = 'contract')}>配置契约</button><button class:active={detailTab === 'versions'} on:click={() => (detailTab = 'versions')}>版本历史</button></nav><div class="persona-detail-scroll">{#if loading}<div class="persona-detail-empty">正在加载版本...</div>{:else if detailTab === 'overview'}<section class="persona-detail-section"><h3>说明</h3><p>{selectedProfile.description || '暂无专家说明。'}</p></section><section class="persona-detail-section"><h3>专家能力</h3><div class="persona-detail-chips"><span>{profileType(selectedProfile)}</span><span>{profileDomain(selectedProfile)}</span><span>{profileCapabilitiesText(selectedProfile)}</span></div></section><section class="persona-detail-section"><h3>当前版本</h3><div class="persona-version-summary"><strong>{selectedVersion ? `v${selectedVersion.version}` : '尚未创建版本'}</strong><span>{selectedVersion ? (selectedVersion.status === 'published' ? '已发布' : '草稿') : '创建版本后可供 Engine 使用'}</span></div><p>{selectedVersion ? String(selectedVersion.config.instruction || '暂无专家指令。') : '请在右下角创建第一个版本。'}</p></section>{:else if detailTab === 'contract'}<section class="persona-detail-section"><h3>模型能力</h3><pre>{JSON.stringify(selectedVersion?.config.capabilities ?? selectedProfile.config.capabilities ?? [], null, 2)}</pre></section><section class="persona-detail-section"><h3>允许工具</h3><pre>{JSON.stringify(selectedVersion?.config.allowed_tools ?? selectedProfile.config.allowed_tools ?? [], null, 2)}</pre></section>{:else}<section class="persona-detail-section"><div class="persona-version-list">{#each versions as version}<button class:selected={version.id === selectedVersionId} on:click={() => (selectedVersionId = version.id)}><span><strong>v{version.version}</strong><small>{version.status === 'published' ? '已发布' : version.status === 'disabled' ? '已停用' : '草稿'} · {formatDate(version.created_at)}</small></span><ChevronRight size={14} /></button>{:else}<span class="muted-copy">暂无版本历史。</span>{/each}</div></section>{/if}</div><div class="persona-detail-footer"><button class="secondary" type="button" on:click={publishVersion} disabled={busy || !selectedVersionId || selectedVersion?.status === 'published'}><ShieldCheck size={14} />发布版本</button><button class="primary" type="button" on:click={startEdit}><Edit3 size={14} />编辑</button></div>{#if editorOpen}<div class="persona-editor-overlay"><div class="persona-editor-heading"><div><p class="eyebrow">PERSONA VERSION</p><h3>{selectedProfile.name}</h3><small>创建不可变版本草稿</small></div><button class="icon-button" type="button" aria-label="关闭编辑" on:click={() => (editorOpen = false)}><X size={17} /></button></div><form class="persona-editor-form" on:submit|preventDefault={createVersion}><label>专家指令<textarea bind:value={profileInstruction} rows="9" required placeholder="描述诊断范围、判断原则和输出要求"></textarea></label><div class="persona-editor-grid"><label>模型能力<input bind:value={profileCapabilities} placeholder="text, tool_calling, stream" /></label><label>允许工具<input bind:value={profileAllowedTools} placeholder="connector_postgresql_inspect" /></label></div><div class="persona-editor-grid"><label>输入 Schema<textarea bind:value={profileInputSchema} rows="7" spellcheck="false"></textarea></label><label>输出 Schema<textarea bind:value={profileOutputSchema} rows="7" spellcheck="false"></textarea></label></div><div class="persona-editor-actions"><button class="secondary" type="button" on:click={() => (editorOpen = false)}>取消</button><button class="primary" disabled={busy || !selectedProfileId}><Plus size={14} />创建版本</button></div></form></div>{/if}</aside>{/if}
</section>
